add_action( 'admin_menu', 'perfectpixel_sales_by_state_menu', 62 );

function perfectpixel_sales_by_state_menu() {
	add_submenu_page( 'woocommerce', 'Πωλήσεις ανά περιοχή', 'Πωλήσεις ανά περιοχή', 'view_woocommerce_reports', 'perfectpixel-sales-by-state', 'perfectpixel_sales_by_state_page' );
}

function perfectpixel_sales_by_state_page() {
	$year = isset( $_GET['year'] ) ? absint( $_GET['year'] ) : (int) current_time( 'Y' );
	$rows = array();
	$page = 1;
	do {
		$orders = wc_get_orders(
			array(
				'status'       => array( 'completed', 'processing' ),
				'date_created' => $year . '-01-01...' . $year . '-12-31',
				'type'         => 'shop_order',
				'limit'        => 200,
				'page'         => $page,
			)
		);
		foreach ( $orders as $order ) {
			$key = $order->get_billing_country() . '|' . $order->get_billing_state();
			if ( ! isset( $rows[ $key ] ) ) {
				$rows[ $key ] = array( 'orders' => 0, 'total' => 0.0 );
			}
			$rows[ $key ]['orders']++;
			$rows[ $key ]['total'] += (float) $order->get_total();
		}
		$page++;
	} while ( count( $orders ) === 200 );
	uasort(
		$rows,
		function ( $a, $b ) {
			return $b['total'] <=> $a['total'];
		}
	);

	echo '<div class="wrap"><h1>Πωλήσεις ανά περιοχή ' . esc_html( $year ) . '</h1><form method="get"><input type="hidden" name="page" value="perfectpixel-sales-by-state"><select name="year">';
	for ( $y = (int) current_time( 'Y' ); $y >= (int) current_time( 'Y' ) - 5; $y-- ) {
		printf( '<option value="%1$d"%2$s>%1$d</option>', $y, selected( $year, $y, false ) );
	}
	echo '</select> <button class="button">Προβολή</button></form>';
	echo '<table class="widefat striped" style="margin-top:1em;max-width:700px"><thead><tr><th>Χώρα</th><th>Περιοχή</th><th>Παραγγελίες</th><th>Σύνολο</th></tr></thead><tbody>';
	$states = WC()->countries->get_states();
	foreach ( $rows as $key => $row ) {
		list( $country, $state ) = array_pad( explode( '|', $key ), 2, '' );
		$country_name = WC()->countries->countries[ $country ] ?? $country;
		$state_name   = $states[ $country ][ $state ] ?? $state;
		printf( '<tr><td>%s</td><td>%s</td><td>%d</td><td>%s</td></tr>', esc_html( $country_name ), esc_html( $state_name ? $state_name : '–' ), (int) $row['orders'], wp_kses_post( wc_price( $row['total'] ) ) );
	}
	if ( ! $rows ) {
		echo '<tr><td colspan="4">Δεν υπάρχουν παραγγελίες για αυτό το έτος.</td></tr>';
	}
	echo '</tbody></table></div>';
}
